import{_ as t,o,c as s,a2 as a}from"./chunks/framework.BN3Eol-0.js";const u=JSON.parse('{"title":"UXD-031 — The station assembly player keeps one height across its phases","description":"","frontmatter":{},"headers":[],"relativePath":"uxs/decisions/UXD-031-station-assembly-player-fixed-box.md","filePath":"uxs/decisions/UXD-031-station-assembly-player-fixed-box.md"}'),n={name:"uxs/decisions/UXD-031-station-assembly-player-fixed-box.md"};function i(d,e,h,r,l,c){return o(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="uxd-031-—-the-station-assembly-player-keeps-one-height-across-its-phases" tabindex="-1">UXD-031 — The station assembly player keeps one height across its phases <a class="header-anchor" href="#uxd-031-—-the-station-assembly-player-keeps-one-height-across-its-phases" aria-label="Permalink to &quot;UXD-031 — The station assembly player keeps one height across its phases&quot;">​</a></h1><ul><li><strong>Status</strong>: accepted (built; checked by e2e on three projects and by screenshots, not yet by the operator)</li><li><strong>Date</strong>: 2026-11-14 (proposed 2026-11-13, decided and built)</li><li><strong>Decider</strong>: the operator, 2026-11-13/14 — the recommendations of <code>docs/wip/2026-11-13-slice-E5-brief.md</code> §12 approved as written (E-decisions 22a and 23a, &quot;approved all E-series recommendations&quot;, <code>docs/wip/2026-11-11-ux-feedback-plan.md</code> &quot;## E. Catalog&quot;)</li><li><strong>Answers</strong>: ISS2 of the UX feedback plan; slice E5</li><li><strong>Builds on</strong>: <a href="./UXD-014-one-chip-and-filter">UXD-014</a> (the control row&#39;s chips)</li><li><strong>Changes</strong>: <code>src/lib/components/StationAssemblyControl.svelte</code> (shared by <code>/iss</code> and <code>/tiangong</code>), <code>src/lib/components/StationAssemblyControl.test.ts</code> (new), <code>tests/e2e/station-assembly-height.spec.ts</code> (new); <code>docs/concept/05_Design_System.md</code> 5.18, <code>docs/adr/TA.md</code>, the component README, the change inventory</li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>The player&#39;s box grew upward with the wrapped text of its &quot;launched on&quot; line. On <code>/iss</code> the phase strings run from 29 to 129 characters (a module, a dock event, a truss install with its crew list), so the play button, the scrub bar and the date moved as the phase changed (ISS2: &quot;changes height as content changes&quot;).</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><ol><li><p><strong>Two fixed rows (E-decision 22a).</strong> The chip is two rows of <code>1.3em</code>, each one line (<code>white-space: nowrap</code>, ellipsis): row 1 the rocket glyph and the phase name (bold; a button to the module&#39;s panel where there is one), row 2 &quot;launcher · date&quot; (the date never cut, the launcher takes the ellipsis). The empty state fills the same two rows. The whole phase text (<code>name · launcher · date</code>) is in the chip&#39;s <code>title</code> and in a visually hidden <code>aria-live=&quot;polite&quot;</code> element, so the cut text is still reachable.</p></li><li><p><strong>The hint (E-decision 23a).</strong> One row with an ellipsis above 480 px; at 480 px and below it reserves two rows (<code>height: 2.5em</code>, clamped at two) so the instruction stays whole and the box never changes height.</p></li><li><p><strong>Both stations.</strong> One component, so <code>/tiangong</code> follows <code>/iss</code>.</p></li><li><p><strong>The control row on a phone.</strong> The scrub input may shrink (<code>min-width: 0</code>) and the date readout is <code>5.5rem</code> at 480 px and below, so the date stays inside the box at 360 and 393 px (it ran past the box edge before).</p></li><li><p><strong>A landscape phone (touch, 480 px tall or less).</strong> The box sits at <code>bottom: 3.5rem</code> with tighter padding (about 124 px tall) so it fits between the top-left HUD chips (3D, RESET VIEW, SPIN) and the drawer tabs. Measured at 802 x 293: before, the box ran from y 68 to 205 and covered the chips&#39; row (bottom 104), hiding the play and reset buttons behind RESET VIEW and SPIN; after, from y 113 to 237, 9 px under the chips and 8 px above the drawer (top 245).</p></li></ol><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>The box height does not depend on the phase, the width or the locale&#39;s phase text; the controls sit at the same y in every phase.</li><li>Crew lists and long launcher strings are cut on screen (full in the title and the live region). The data is unchanged.</li><li>On a 360 to 393 px phone the scrub bar is short (about 50 to 110 px) because the three 44 px touch chips and the date take the row.</li></ul><h2 id="not-done" tabindex="-1">Not done <a class="header-anchor" href="#not-done" aria-label="Permalink to &quot;Not done&quot;">​</a></h2><ul><li>No data edit (the dock and truss strings stay English constants in every locale; not touched).</li><li>No layout outside the player was changed. The landscape fit (decision 5) is by media query on height; a landscape window shorter than about 290 px was not measured.</li><li>The live region&#39;s addition is small and was not asked for in the plan; a reviewer may cut it.</li></ul><h2 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification&quot;">​</a></h2><p><code>StationAssemblyControl.test.ts</code> (two chip rows in both states, the title and live text, the stylesheet&#39;s fixed heights and the 480 px rule, the phase data&#39;s second-row fields) and <code>tests/e2e/station-assembly-height.spec.ts</code> (60 scrub positions on <code>/iss</code> and <code>/tiangong</code> in en, de and ar: box height, box top and the y of play, scrub, date, chip and hint within 1 px, the date inside the box, the box inside the viewport and clear of the drawer; also at 360 px; desktop, mobile and mobile-landscape projects). Run counts are in the E5 row of the change inventory.</p>',12)])])}const b=t(n,[["render",i]]);export{u as __pageData,b as default};
